    // inlining of macro cuddRef
    cuddSatInc(Cudd_Regular(N).ref);
    if st__insert(storeTable, (char *)N, NIL(char)) == st__OUT_OF_MEM {
        fmt.Fprintf(dd.err, "Something wrong, st__table insert failed\n");
