    // inlining of macro Cudd_Regular
    Nt = ((((DdNode *)((ptruint)(N) & ~01))).type.kids.T);
    // inlining of macro Cudd_E
    // inlining of macro Cudd_Regular
    Ne = ((((DdNode *)((ptruint)(N) & ~01))).type.kids.E);

